        if (needsDateSwitch) setBrowsingDate(day);
        const flash = () => {
          const targetElement = Array.from(
            document.querySelectorAll("#today-journal-stream [data-log-id], #today-journal-stream [data-journal-id]")
          ).find((el) => String(el.dataset.logId || el.dataset.journalId) === String(targetLogId));
          if (!targetElement) return;
          targetElement.scrollIntoView({ behavior: "smooth", block: "center" });
          targetElement.classList.add("ring-2", "ring-amber-400", "bg-amber-50/60", "transition-all", "duration-500");
          setTimeout(() => {
            targetElement.classList.remove("ring-2", "ring-amber-400", "bg-amber-50/60");
          }, 1500);
        };
        setTimeout(flash, needsDateSwitch ? 120 : 40);
