        plannerState.mode = mode;
        calMode = mode === "year" || mode === "day" || mode === "parking" ? "month" : mode;
        calCursor = plannerState.currentDate;
        paintPlannerModeButtons();
        showPlannerContainer(mode);
        updatePlannerLabel();
