          return `<button type="button" data-planner-day="${value}" class="min-w-0 border-r border-slate-100 px-0.5 py-2 text-center last:border-r-0 ${isToday ? "bg-indigo-50/80" : ""}">
            <span class="block text-[10px] font-bold uppercase tracking-wider text-slate-400">${WEEK_SHORT_MON[index]}</span>
            <span class="mt-1 inline-flex h-6 w-6 items-center justify-center rounded-full text-xs font-extrabold ${isToday ? "bg-slate-900 text-white" : "text-slate-800"}">${day.getDate()}</span>
          </button>`;
