          const eventTheme = items.some((task) => isEventEntry(task) && task.is_theme_of_day);
          const hasTheme = pads.some((pad) => pad.is_theme_of_day) || eventTheme;
          const notepadRibbon = pads.slice(0, 2).map((pad) => notepadCalPill(pad, value)).join("");
          const notepadMore = pads.length > 2
            ? `<span class="mb-1 block truncate px-1 text-[10px] text-slate-400">+${pads.length - 2} notes</span>`
            : "";
          const pills = items.slice(0, 3).map((task) => {
            const done = taskIsComplete(task);
            return `<span class="mb-1 block truncate rounded px-1.5 py-0.5 text-[11px] leading-snug ${done ? "bg-slate-100 text-slate-400 line-through" : "border border-slate-100 bg-white font-semibold text-slate-700"}">${task.is_routine ? "🔁 " : ""}${escapeHtml(taskTitle(task))}</span>`;
          }).join("");
