        const status = document.getElementById("photo-camera-status");
        const snap = document.getElementById("photo-camera-snap");
        if (!modal || !video) {
          window.alert("Camera viewfinder is unavailable.");
          return;
        }
        if (!navigator.mediaDevices?.getUserMedia) {
          document.getElementById("photo-camera-input")?.click();
          return;
        }
