        if (html === "<br>" || html === "<div><br></div>") html = "";
        const titleEl = document.querySelector(`[data-note-title-input="${noteId}"]`);
        const title = (titleEl?.value || "").trim() || "Untitled Note";
        noteEditKeys.delete(noteKey(noteId));
