      async function createBlankNote({ projectId, phaseId = null } = {}) {
        const res = await fetch("/api/notes", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            project_id: Number(projectId),
            phase_id: phaseId || null,
            title: "Untitled Note",
            content: "",
          }),
        });
        if (!res.ok) {
          window.alert("Could not create note.");
          return null;
        }
        const note = await res.json();
        upsertLocalNote(note);
        noteEditKeys.add(noteKey(note.id));
        await loadAll();
        beginNoteEdit(note.id);
        return note;
      }
      function upsertLocalNote(note) {
        const project = (stores.project || []).find((item) => Number(item.id) === Number(note.project_id));
        if (!project) return;
        if (note.phase_id) {
          const phase = findPhase(project, note.phase_id);
          if (!phase) return;
          phase.notes = [note, ...(phase.notes || []).filter((row) => Number(row.id) !== Number(note.id))];
        } else {
          project.notes = [note, ...(project.notes || []).filter((row) => Number(row.id) !== Number(note.id))];
        }
      }
      async function deleteNoteById(noteId) {
        const res = await fetch(`/api/notes/${noteId}`, { method: "DELETE" });
        if (!res.ok) {
          window.alert("Could not delete note.");
          return;
        }
        noteDeleteConfirmKey = null;
        noteEditKeys.delete(noteKey(noteId));
        await loadAll();
      }
