        if (!indexPanel || !chapterPanel || !coverPanel) return;
        const chapters = vaultNotebookDetail?.chapters || [];
        const showCover = vaultEdgeMode === "cover";
        const showIndex = vaultEdgeMode === "index";
        const showChapter = vaultEdgeMode === "chapter";
        coverPanel.classList.toggle("hidden", !showCover);
        indexPanel.classList.toggle("hidden", !showIndex);
