      async function saveRewardEditor(reward) {
        const clearing = !reward || !reward.title;
        const { type, id } = rewardEditTarget || {};
        if (type === "habit" && !id) {
          habitCurrentReward = clearing ? null : { ...reward };
          paintHabitRewardDisplay(habitCurrentReward);
          return { reward: habitCurrentReward };
        }
        if (!id) return null;
        const endpoint = type === "project"
          ? `/api/workbench/projects/${encodeURIComponent(id)}/reward`
          : type === "habit"
            ? `/api/habits/${encodeURIComponent(id)}/reward`
            : `/api/vision/${encodeURIComponent(id)}/reward`;
        const body = type === "habit"
          ? { title: reward?.title, elements: reward?.elements || [], target_streak: reward?.target_streak || 7, reward }
          : { title: reward.title, elements: reward.elements || [] };
        const res = await fetch(endpoint, clearing
          ? { method: "DELETE" }
          : {
              method: "PATCH",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify(type === "habit" ? body : { title: reward.title, elements: reward.elements || [] }),
            });
        if (!res.ok) {
          const err = await res.json().catch(() => ({}));
          throw new Error(err.detail || "Could not save reward");
        }
        const saved = await res.json();
        if (type === "project") {
          upsert(saved);
          paintProjectRewardDisplay(saved.reward);
        } else if (type === "habit") {
          upsert(saved);
          paintHabitRewardDisplay(saved.reward);
        } else {
          upsertVision(saved);
          paintVisionRewardDisplay(saved.reward);
        }
        return saved;
      }
      async function saveVisionReward(reward) {
        rewardEditTarget = { type: "vision", id: Number(visionDetailId) || visionDetailId };
        return saveRewardEditor(reward);
      }
