      async function commitDoItNowItem(item, todayStr, timeStr) {
        const title = String(item?.title || "Focus task").trim() || "Focus task";
        const isSpark = item?.kind === "spark" || item?.item_type === "spark" || Boolean(item?._sparkId);
        const sparkId = item?._sparkId || (isSpark ? item.id : null);

        if (isSpark || sparkId) {
          const spark = (stores.spark || []).find((row) => String(row.id) === String(sparkId || item.id)) || item;
          const res = await fetch("/api/tasks", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              title: spark.title || title,
              assignee: document.getElementById("process-assignee")?.value?.trim() || spark.assignee || "Me",
              due_date: todayStr,
              start_date: todayStr,
              end_date: todayStr,
              start_time: timeStr,
              end_time: null,
              due_time: timeStr,
              is_parked: false,
              is_done: false,
              task_status: "pending",
              raw_content: spark.raw_content || null,
              notes: spark.raw_content ? `<p>${escapeHtml(spark.raw_content)}</p>` : `<p>⚡ Started via Do It Now.</p>`,
            }),
          });
          if (!res.ok) {
            const detail = await res.json().catch(() => ({}));
            showAppToast(detail.detail || "Could not start this spark.");
            return null;
          }
          const task = await res.json();
          await removeSparkFromInbox(spark.id);
          if (task) {
            const idx = stores.task.findIndex((row) => String(row.id) === String(task.id));
            if (idx >= 0) stores.task[idx] = task;
            else stores.task.unshift(task);
          }
          return task;
        }

        const task = (stores.task || []).find((row) => String(row.id) === String(item.id)) || item;
        if (!task?.id) return null;
        const res = await fetch(`/api/tasks/${task.id}`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            title: task.title || title,
            due_date: todayStr,
            start_date: todayStr,
            end_date: todayStr,
            start_time: timeStr,
            end_time: null,
            due_time: timeStr,
            is_parked: false,
            is_done: false,
            task_status: "pending",
            is_routine: false,
            recurrence_days: [],
            assignee: task.assignee || "Me",
            project_id: task.project_id || null,
            phase_id: task.phase_id || null,
          }),
        });
        if (!res.ok) {
          const detail = await res.json().catch(() => ({}));
          showAppToast(detail.detail || "Could not start this task.");
          return null;
        }
        const saved = await res.json();
        const idx = stores.task.findIndex((row) => String(row.id) === String(task.id));
        if (idx >= 0) stores.task[idx] = saved;
        else stores.task.unshift(saved);
        return saved;
      }

      function promptDoItNowTimer(taskTitle) {
        return new Promise((resolve) => {
          const modal = document.getElementById("do-it-now-modal");
          const titleEl = document.getElementById("do-it-now-title");
          const messageEl = document.getElementById("do-it-now-message");
          const conflict = document.getElementById("do-it-now-conflict");
          const presets = document.getElementById("do-it-now-presets");
          if (!modal || !titleEl || !messageEl || !conflict || !presets) {
            resolve({ action: "cancel" });
            return;
          }

          let pendingOverwrite = false;
          const running = Boolean(FocusTimerManager?.isRunning);
          const finish = (result) => {
            modal.removeEventListener("click", onClick);
            closeOverlay("do-it-now-modal");
            resolve(result);
          };
          const showPresets = (overwrite) => {
            pendingOverwrite = Boolean(overwrite);
            conflict.classList.add("hidden");
            presets.classList.remove("hidden");
            titleEl.textContent = `Start "${taskTitle}"`;
            messageEl.textContent = overwrite
              ? "Choose a duration for the new focus timer."
              : "Start a focus timer, or begin without one.";
          };

          if (running) {
            const label = FocusTimerManager.activeTaskTitle || "Current Session";
            const left = FocusTimerManager.getFormattedTime();
            titleEl.textContent = "Focus Timer Already Active";
            messageEl.textContent = `A timer is currently active for "${label}" (${left} remaining).`;
            conflict.classList.remove("hidden");
            presets.classList.add("hidden");
          } else {
            showPresets(false);
          }

          function onClick(event) {
            const closeBtn = event.target.closest?.("[data-close='do-it-now-modal']");
            if (closeBtn || event.target === modal) {
              event.preventDefault();
              event.stopPropagation();
              finish({ action: "cancel" });
              return;
            }
            const actionBtn = event.target.closest?.("[data-do-now-action]");
            if (actionBtn) {
              event.preventDefault();
              event.stopPropagation();
              const action = actionBtn.dataset.doNowAction;
              if (action === "cancel") {
                finish({ action: "cancel" });
                return;
              }
              if (action === "keep") {
                finish({ action: "start", minutes: 0, overwrite: false });
                return;
              }
              if (action === "overwrite") {
                showPresets(true);
                return;
              }
            }
            const minsBtn = event.target.closest?.("[data-do-now-minutes]");
            if (minsBtn) {
              event.preventDefault();
              event.stopPropagation();
              finish({
                action: "start",
                minutes: Number(minsBtn.dataset.doNowMinutes) || 0,
                overwrite: pendingOverwrite,
              });
            }
          }

          modal.addEventListener("click", onClick);
          openOverlay("do-it-now-modal");
        });
      }

      async function executeDoItNow(item) {
        if (!item) return null;
        const title = String(item.title || "Focus task").trim() || "Focus task";
        const choice = await promptDoItNowTimer(title);
        if (!choice || choice.action === "cancel") return null;

        const now = new Date();
        const todayStr = ymd(now);
        const currentTimeStr = getLocalTimeString(now);

        if (choice.overwrite && FocusTimerManager?.isRunning) {
          FocusTimerManager.stop({ silent: true });
        }

        const saved = await commitDoItNowItem(item, todayStr, currentTimeStr);
        if (!saved) return null;

        if (choice.minutes > 0) {
          FocusTimerManager.start(choice.minutes, title);
        }

        showAppToast(`⚡ Started: "${title}" at ${currentTimeStr}`);
        closeOverlay("process-modal");
        plannerState.currentDate = now;
        calCursor = now;
        selectedDate = todayStr;
        showView("tasks");
        await switchPlannerMode("day");
        return saved;
      }

      async function triageDoNowSpark() {
        const spark = (stores.spark || []).find((item) => String(item.id) === String(processSparkId));
        if (!spark) return;
        await executeDoItNow({ ...spark, kind: "spark", _sparkId: spark.id });
      }

