                timing_mode: opts.timingMode || eventItem.timing_mode || eventItem.extra_data?.timing_mode || "point",
                accent_color: eventItem.accent_color || "lavender",
                emoji: eventItem.emoji || null,
                end_time: opts.endTime || eventItem.end_time || null,
                ...natureFields,
