          if (id === "event-editor-modal") {
            cancelEventSetup();
            return;
          }
          if (id === "task-drawer") {
            cancelTaskSetup();
            return;
          }
          if (id === "event-log-editor-modal") {
            closeEventLogEditor();
            return;
          }
          if (id === "task-log-editor-modal") {
            cancelTaskLogEditor();
            return;
          }
          if (id === "log-editor-modal") {
            closeLogEditor();
            return;
          }
          closeOverlay(id);
