      async function saveNotepadSetup() {
        if (!notepadDraft) return;
        const error = document.getElementById("notepad-edit-error");
        syncNotepadNoteEditorsFromDom();
        document.querySelectorAll("[data-notepad-check-text]").forEach((input) => {
          const blockIndex = Number(input.dataset.notepadCheckText);
          const itemIndex = Number(input.dataset.itemIndex);
          const block = notepadDraft.blocks?.[blockIndex];
          if (!block || block.type !== "checklist") return;
          block.items = normalizeNotepadBlockItems(block.items || []);
          if (block.items[itemIndex]) {
            block.items[itemIndex].text = String(input.value || "").trim();
          }
        });
        const blocks = normalizeSparkBlocks(notepadDraft.blocks || []).map((block) => {
          if (block.type === "note") {
            const next = { ...block };
            delete next.editing;
            return next;
          }
          if (block.type === "checklist") {
            const next = {
              ...block,
              items: normalizeNotepadBlockItems(block.items || []),
            };
            delete next.editing;
            return next;
          }
          return block;
        });
        const body = {
          title: document.getElementById("notepad-edit-title").value.trim() || "Notepad",
          pad_type: "text",
          scope: notepadDraft.scope || "day",
          start_date: document.getElementById("notepad-edit-start").value || null,
          end_date: document.getElementById("notepad-edit-end").value || null,
          linked_phase_id: notepadDraft.linked_phase_id || null,
          linked_project_id: notepadDraft.linked_project_id || null,
          is_theme_of_day: false,
          color: notepadColorOf(notepadDraft),
          color_theme: notepadColorOf(notepadDraft),
          content: encodeNotepadPayload(blocks),
        };
        let res;
        if (notepadDraft.id) {
          res = await fetch(`/api/notepads/${notepadDraft.id}`, {
            method: "PATCH",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(body),
          });
        } else {
          res = await fetch("/api/notepads", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(body),
          });
        }
        if (!res.ok) {
          const detail = await res.json().catch(() => ({}));
          if (error) {
            error.textContent = detail.detail || "Could not save notepad.";
            error.classList.remove("hidden");
          }
          return;
        }
        const saved = await res.json();
        saved.blocks = notepadBlocksOf(saved);
        const focusDay = notepadDraft._focusDayAfterSave || null;
        upsertNotepad(saved);
        closeOverlay("notepad-modal");
        await refreshNotepadHome();
        renderProjects();
        if (focusDay) focusPlannerDay(focusDay);
      }
      document.getElementById("btn-save-notepad")?.addEventListener("click", (event) => {
        event.preventDefault();
        void saveNotepadSetup();
      });
      document.getElementById("notepad-form").addEventListener("submit", async (event) => {
        event.preventDefault();
        await saveNotepadSetup();
      });
      document.getElementById("notepad-add-block-btn")?.addEventListener("click", (event) => {
        event.preventDefault();
        const menu = document.getElementById("notepad-add-block-menu");
        if (!menu) return;
        setNotepadAddBlockMenuOpen(menu.classList.contains("hidden"));
      });
      document.getElementById("notepad-add-block-menu")?.addEventListener("click", async (event) => {
        const btn = event.target.closest("[data-notepad-add-block]");
        if (!btn || !notepadDraft) return;
        const kind = btn.dataset.notepadAddBlock;
        setNotepadAddBlockMenuOpen(false);
        if (kind === "photo") {
          document.getElementById("notepad-editor-photo-input")?.click();
          return;
        }
        if (kind === "link") {
          if (typeof showFieldPopover !== "function") return;
          showFieldPopover({
            title: "Link block",
            label: "Paste a URL",
            placeholder: "https://…",
            value: "https://",
            inputType: "url",
            confirmLabel: "Attach link",
            anchor: document.getElementById("notepad-add-block-btn"),
            secondary: {
              label: "Title (optional)",
              placeholder: "Custom label",
              value: "",
            },
            onSubmit: (value, customTitle) => {
              const cleaned = String(value || "").trim();
              if (!cleaned) return;
              let title = String(customTitle || "").trim();
              if (!title) {
                try { title = new URL(cleaned).hostname.replace(/^www\./, "") || cleaned; } catch (_) { title = cleaned; }
              }
              const block = {
                id: newBlockId(),
                type: "link",
                url: cleaned,
                title,
                display_mode: "compact",
                preview_image: "",
                description: "",
                preview: null,
              };
              notepadDraft.blocks = notepadDraft.blocks || [];
              notepadDraft.blocks.push(block);
              uBlockSettingsKey = uBlockKey("notepad-draft", block.id);
              renderNotepadEditorBlocks();
            },
          });
          return;
        }
        if (kind === "checklist") {
          notepadDraft.blocks = notepadDraft.blocks || [];
          notepadDraft.blocks.push({
            id: newBlockId(),
            type: "checklist",
            title: "Checklist",
            items: [],
            expanded: true,
            editing: true,
          });
          renderNotepadEditorBlocks();
          return;
        }
        if (kind === "note") {
          notepadDraft.blocks = notepadDraft.blocks || [];
          notepadDraft.blocks.push({
            id: newBlockId(),
            type: "note",
            title: "Rich Note",
            html: "",
            expanded: true,
            editing: true,
          });
          renderNotepadEditorBlocks();
        }
      });
      document.getElementById("notepad-editor-photo-input")?.addEventListener("change", async (event) => {
        const file = event.target.files?.[0];
        event.target.value = "";
        if (!file || !notepadDraft) return;
        try {
          let url = await new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(String(reader.result || ""));
            reader.onerror = () => reject(reader.error || new Error("read fail"));
            reader.readAsDataURL(file);
          });
          const form = new FormData();
          form.append("file", file);
          const res = await fetch("/api/upload", { method: "POST", body: form });
          if (res.ok) {
            const uploaded = await res.json();
            url = uploaded.url || url;
          }
          const block = {
            id: newBlockId(),
            type: "photo",
            url,
            caption: "",
            filename: file.name || "",
            size: "compact",
          };
          notepadDraft.blocks = notepadDraft.blocks || [];
          notepadDraft.blocks.push(block);
          uBlockSettingsKey = uBlockKey("notepad-draft", block.id);
          renderNotepadEditorBlocks();
        } catch (_) {
          const error = document.getElementById("notepad-edit-error");
          if (error) {
            error.textContent = "Could not attach that photo.";
            error.classList.remove("hidden");
          }
        }
      });
      document.getElementById("notepad-editor-blocks")?.addEventListener("click", (event) => {
        if (!notepadDraft) return;
        if (event.target.closest("[data-ublock]")) return;
        const remove = event.target.closest("[data-notepad-remove-block]");
        if (remove) {
          event.preventDefault();
          event.stopPropagation();
          const index = Number(remove.dataset.notepadRemoveBlock);
          if (!Number.isNaN(index)) {
            syncNotepadNoteEditorsFromDom();
            notepadDraft.blocks.splice(index, 1);
            renderNotepadEditorBlocks();
          }
          return;
        }
        const doneNote = event.target.closest("[data-notepad-done-note]");
        if (doneNote) {
          event.preventDefault();
          event.stopPropagation();
          const index = Number(doneNote.dataset.notepadDoneNote);
          if (!Number.isNaN(index)) commitNotepadNoteBlock(index);
          return;
        }
        const editNote = event.target.closest("[data-notepad-edit-note]");
        if (editNote) {
          event.preventDefault();
          event.stopPropagation();
          const index = Number(editNote.dataset.notepadEditNote);
          if (!Number.isNaN(index)) setNotepadNoteBlockEditing(index, true);
          return;
        }
        const activateNote = event.target.closest("[data-notepad-activate-note]");
        if (activateNote && !event.target.closest("button")) {
          event.preventDefault();
          const index = Number(activateNote.dataset.notepadActivateNote);
          if (!Number.isNaN(index)) setNotepadNoteBlockEditing(index, true);
          return;
        }
        const doneCheck = event.target.closest("[data-notepad-done-check]");
        if (doneCheck) {
          event.preventDefault();
          event.stopPropagation();
          const index = Number(doneCheck.dataset.notepadDoneCheck);
          document.querySelectorAll(`[data-notepad-check-text="${index}"]`).forEach((input) => {
            const itemIndex = Number(input.dataset.itemIndex);
            const block = notepadDraft.blocks?.[index];
            if (!block || block.type !== "checklist") return;
            block.items = normalizeNotepadBlockItems(block.items || []);
            if (block.items[itemIndex]) block.items[itemIndex].text = String(input.value || "").trim();
          });
          if (!Number.isNaN(index)) setNotepadNoteBlockEditing(index, false);
          return;
        }
        const editCheck = event.target.closest("[data-notepad-edit-check], [data-notepad-activate-check]");
        if (editCheck) {
          event.preventDefault();
          event.stopPropagation();
          const index = Number(editCheck.dataset.notepadEditCheck || editCheck.dataset.notepadActivateCheck);
          if (!Number.isNaN(index)) setNotepadNoteBlockEditing(index, true);
          return;
        }
        const toggleItem = event.target.closest("[data-notepad-check-toggle]");
        if (toggleItem) {
          event.preventDefault();
          const blockIndex = Number(toggleItem.dataset.notepadCheckToggle);
          const itemIndex = Number(toggleItem.dataset.itemIndex);
          const block = notepadDraft.blocks?.[blockIndex];
          if (block?.type === "checklist" && block.items?.[itemIndex]) {
            block.items[itemIndex].done = !block.items[itemIndex].done;
            renderNotepadEditorBlocks();
          }
          return;
        }
        const removeItem = event.target.closest("[data-notepad-check-remove]");
        if (removeItem) {
          event.preventDefault();
          const blockIndex = Number(removeItem.dataset.notepadCheckRemove);
          const itemIndex = Number(removeItem.dataset.itemIndex);
          const block = notepadDraft.blocks?.[blockIndex];
          if (block?.type === "checklist") {
            block.items = normalizeNotepadBlockItems(block.items || []);
            block.items.splice(itemIndex, 1);
            renderNotepadEditorBlocks();
          }
          return;
        }
        const addItem = event.target.closest("[data-notepad-check-add]");
        if (addItem) {
          event.preventDefault();
          const blockIndex = Number(addItem.dataset.notepadCheckAdd);
          const block = notepadDraft.blocks?.[blockIndex];
          const input = document.querySelector(`[data-notepad-check-new="${blockIndex}"]`);
          const text = String(input?.value || "").trim();
          if (block?.type === "checklist" && text) {
            block.items = normalizeNotepadBlockItems(block.items || []);
            block.items.push({ id: newBlockId(), text, done: false });
            if (input) input.value = "";
            renderNotepadEditorBlocks();
          }
        }
      });
