      async function saveProject(projectId, fields, { skipReload = false } = {}) {
        const res = await fetch(`/api/workbench/projects/${projectId}`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(fields),
        });
        if (!res.ok) return null;
        const saved = await res.json();
        const index = stores.project.findIndex((row) => row.id === Number(projectId));
        if (index >= 0) {
          const prev = stores.project[index];
          stores.project[index] = {
            ...prev,
            ...saved,
            title: saved.title ?? prev.title,
            phases: prev.phases,
            phase_tree: prev.phase_tree,
            tasks: prev.tasks,
            extra_data: prev.extra_data,
            color_theme: saved.color_theme ?? prev.color_theme,
            deadline: "deadline" in saved ? saved.deadline : prev.deadline,
            details: saved.details ?? prev.details,
            links: saved.links ?? prev.links,
            attachments: saved.attachments ?? prev.attachments,
            canvas_items: saved.canvas_items ?? prev.canvas_items,
          };
        }
        if (skipReload) {
          const titleEl = document.querySelector(`[data-project-title="${projectId}"]`);
          if (titleEl && saved.title) titleEl.textContent = saved.title;
          return saved;
        }
        await loadAll();
        return saved;
      }
      async function savePhase(projectId, phaseId, fields, { skipReload = false } = {}) {
        const before = stores.project.find((item) => item.id === Number(projectId));
        const beforeProgress = before ? projectProgress(before) : { done: 0, total: 0 };
        const wasComplete = beforeProgress.total > 0 && beforeProgress.done === beforeProgress.total;
        const wasActive = !before || projectIsActive(before);
        const res = await fetch(`/api/workbench/projects/${projectId}/phases/${encodeURIComponent(phaseId)}`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(fields),
        });
        if (!res.ok) return null;
        const saved = await res.json();
        queueUnlockedRewards(saved.unlocked_rewards);
        if (skipReload) {
          const project = stores.project.find((item) => item.id === Number(projectId));
          const phase = findPhase(project, phaseId);
          if (phase && "details" in fields) phase.details = fields.details;
          return saved;
        }
        await loadAll();
        const after = stores.project.find((item) => item.id === Number(projectId));
        if (wasActive && !wasComplete && after && projectLifecycle(after) === "completed") showProjectCelebrate(after.title);
        return saved;
      }
      function beginProjectRename(card, projectId) {
        const project = stores.project.find((item) => String(item.id) === String(projectId));
        if (!project || card.querySelector("[data-project-rename-input]")) return;
        const title = card.querySelector(`[data-project-title="${projectId}"]`);
        if (!title) return;
        const toggle = title.closest("[data-toggle-project]");
        const chevron = toggle?.querySelector(".phase-chevron");
        const input = document.createElement("input");
        input.type = "text";
        input.dataset.projectRenameInput = String(projectId);
        input.value = project.title;
        input.className = "min-h-10 min-w-0 flex-1 rounded-xl bg-white px-3 text-xl font-bold outline-none ring-2 ring-spark-iris/30";
        const row = document.createElement("div");
        row.className = "flex min-h-12 min-w-0 flex-1 items-center gap-2 rounded-2xl px-1";
        row.dataset.projectRenameRow = String(projectId);
        if (chevron) row.appendChild(chevron.cloneNode(true));
        row.appendChild(input);
        if (toggle) toggle.replaceWith(row);
        else title.replaceWith(input);
        input.focus();
        input.select();
        let finished = false;
        let cancelled = false;
        const finish = async () => {
          if (finished) return;
          finished = true;
          if (cancelled) {
            renderProjects();
            return;
          }
          const next = input.value.trim();
          if (next && next !== project.title) {
            await saveProject(project.id, { title: next });
          } else {
            renderProjects();
          }
        };
        const stopSpace = (event) => {
          if (event.key === " " || event.code === "Space" || event.keyCode === 32) {
            event.stopPropagation();
          }
        };
        input.addEventListener("keydown", (event) => {
          stopSpace(event);
          if (event.key === "Enter") {
            event.preventDefault();
            event.stopPropagation();
            input.blur();
            return;
          }
          if (event.key === "Escape") {
            event.preventDefault();
            event.stopPropagation();
            cancelled = true;
            input.value = project.title;
            input.blur();
          }
        });
        input.addEventListener("keyup", stopSpace);
        input.addEventListener("keypress", stopSpace);
        input.addEventListener("click", (event) => event.stopPropagation());
        input.addEventListener("pointerdown", (event) => event.stopPropagation());
        row.addEventListener("click", (event) => event.stopPropagation());
        input.addEventListener("blur", finish);
      }
