        const links = logLinks.map((item) => ({ url: item.url, title: item.title || item.url }));
        const files = logFiles.filter((item) => item?.url).map((item) => ({
          name: item.name || "File",
          url: item.url,
          size: item.size || 0,
        }));
        const primary = metrics[0] || null;
        const measuredValue = primary ? values[primary.name] : null;
        const fields = {
          completed: Boolean(completed),
          reflection_html: reflectionHtml || undefined,
          note: reflectionHtml || undefined,
          measured_value: measuredValue != null ? measuredValue : undefined,
          measured_unit: primary?.unit || habitExtra(habit || {}).measure_unit || "",
          target_value: primary?.target ?? habitExtra(habit || {}).measure_target ?? undefined,
          photos: types.includes("photo") ? photos : undefined,
          links: types.includes("link") ? links : undefined,
          files: types.includes("file") ? files : undefined,
          link: types.includes("link") ? (links[0]?.url || "") : undefined,
          attachment_url: photos[0]?.url || files[0]?.url || "",
        };
        if (Object.keys(values).length) fields.values = values;
