      document.getElementById("legacy-filter-bar")?.addEventListener("click", async (event) => {
        const btn = event.target.closest("[data-legacy-filter]");
        if (!btn) return;
        const type = btn.dataset.legacyFilter;
        if (type === "all") {
          legacyFilter = { type: "all", val: null, start: null, end: null };
        } else if (type === "year") {
          legacyFilter = { type: "year", val: String(new Date().getFullYear()), start: null, end: null };
        } else if (type === "month") {
          const now = new Date();
          legacyFilter = {
            type: "month",
            val: `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`,
            start: null,
            end: null,
          };
        } else if (type === "range") {
          legacyFilter = { ...legacyFilter, type: "range" };
          const rangeBox = document.getElementById("legacy-range-inputs");
          rangeBox?.classList.remove("hidden");
          paintLegacyFilterBar();
          return;
        }
        legacySelectedId = null;
        await renderLegacyPage();
      });
      document.getElementById("legacy-range-apply")?.addEventListener("click", async () => {
        legacyFilter = {
          type: "range",
          val: null,
          start: document.getElementById("legacy-range-start")?.value || null,
          end: document.getElementById("legacy-range-end")?.value || null,
        };
        legacySelectedId = null;
        await renderLegacyPage();
      });
