      async function uploadRewardPhoto(input, targetId) {
        const file = input.files?.[0];
        if (!file) return;
        const body = new FormData();
        body.append("file", file);
        const res = await fetch("/api/upload", { method: "POST", body });
        input.value = "";
        if (!res.ok) return;
        const uploaded = await res.json();
        const target = document.getElementById(targetId);
        if (target) target.value = uploaded.url;
      }
      document.getElementById("habit-reward-upload")?.addEventListener("change", (event) => uploadRewardPhoto(event.target, "habit-reward-photo"));
      document.getElementById("vision-reward-display-container").addEventListener("click", async (event) => {
        if (event.target.closest("[data-open-reward-editor='vision']") || event.target.closest("#btn-open-reward-modal")) {
          openVisionRewardModal();
          return;
        }
        if (event.target.closest("[data-remove-reward='vision']") || event.target.closest("#btn-remove-vision-reward")) {
          if (!window.confirm("Remove this graduation reward?")) return;
          try {
            rewardEditTarget = { type: "vision", id: Number(visionDetailId) || visionDetailId };
            await saveRewardEditor(null);
          } catch (err) {
            window.alert(err.message || "Could not remove reward.");
          }
        }
      });
      document.getElementById("vision-reward-form").addEventListener("click", async (event) => {
        const add = event.target.closest("[data-reward-add]");
        if (add) {
          paintRewardElementDraft(add.dataset.rewardAdd);
          return;
        }
        if (event.target.closest("[data-reward-draft-cancel]")) {
          paintRewardElementDraft(null);
          return;
        }
        const remove = event.target.closest("[data-reward-remove]");
        if (remove) {
          visionRewardDraft.elements.splice(Number(remove.dataset.rewardRemove), 1);
          paintRewardElementsList();
          return;
        }
        if (event.target.closest("[data-reward-draft-confirm]")) {
          const kind = visionRewardDraftKind;
          const error = document.getElementById("reward-modal-error");
          error.classList.add("hidden");
          if (kind === "photo") {
            const url = document.getElementById("reward-draft-url")?.value.trim();
            if (!url) {
              error.textContent = "Add a photo URL or upload an image first.";
              error.classList.remove("hidden");
              return;
            }
            visionRewardDraft.elements.push({ type: "photo", url, title: url.split("/").pop() || "" });
          } else if (kind === "link") {
            const title = document.getElementById("reward-draft-title")?.value.trim() || "";
            const url = document.getElementById("reward-draft-url")?.value.trim() || "";
            if (!url) {
              error.textContent = "Add a product link URL.";
              error.classList.remove("hidden");
              return;
            }
            visionRewardDraft.elements.push({ type: "link", title: title || url, url });
          } else if (kind === "note") {
            const content = document.getElementById("reward-draft-note")?.value.trim() || "";
            if (!content) {
              error.textContent = "Write a short note.";
              error.classList.remove("hidden");
              return;
            }
            visionRewardDraft.elements.push({ type: "note", content });
          } else if (kind === "file") {
            const url = document.getElementById("reward-draft-url")?.value.trim() || "";
            if (!url) {
              error.textContent = "Choose a file to upload first.";
              error.classList.remove("hidden");
              return;
            }
            const name = document.getElementById("reward-draft-file-name")?.textContent || url.split("/").pop() || "File";
            visionRewardDraft.elements.push({ type: "file", url, title: name });
          }
          paintRewardElementDraft(null);
          paintRewardElementsList();
        }
      });
      document.getElementById("vision-reward-form").addEventListener("change", async (event) => {
        const fileInput = event.target.closest("#reward-draft-file");
        if (!fileInput || !fileInput.files?.[0]) return;
        const body = new FormData();
        body.append("file", fileInput.files[0]);
        const res = await fetch("/api/upload", { method: "POST", body });
        if (!res.ok) return;
        const uploaded = await res.json();
        const urlField = document.getElementById("reward-draft-url");
        if (urlField) urlField.value = uploaded.url || "";
        const nameEl = document.getElementById("reward-draft-file-name");
        if (nameEl) {
          nameEl.textContent = fileInput.files[0].name;
          nameEl.classList.remove("hidden");
        }
      });
      document.getElementById("vision-reward-form").addEventListener("submit", async (event) => {
        event.preventDefault();
        const error = document.getElementById("reward-modal-error");
        const title = document.getElementById("reward-modal-title").value.trim();
        if (!title) {
          error.textContent = "Add a trophy title.";
          error.classList.remove("hidden");
          return;
        }
        try {
          const streak = Math.max(1, Number(document.getElementById("reward-target-streak")?.value) || visionRewardDraft.target_streak || 7);
          await saveRewardEditor({
            title,
            elements: visionRewardDraft.elements || [],
            target_streak: rewardEditTarget?.type === "habit" ? streak : undefined,
          });
          closeOverlay("modal-vision-reward");
        } catch (err) {
          error.textContent = err.message || "Could not save reward.";
          error.classList.remove("hidden");
        }
      });

      function bootSparksApp() {
        forceClearBlockingOverlays();
        try { ensureChipUiOnBody(); } catch (_) {}
        try { wireUniversalBlockEngine(); } catch (_) {}
        if (!window.UniversalCanvasEditor) {
          console.error("UniversalCanvasEditor failed to load");
        }
        loadAll().catch(() => {
          document.getElementById("spark-empty").classList.remove("hidden");
          document.getElementById("spark-empty").textContent = "Could not load Sparks. Is the server running?";
        });
      }
      if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", bootSparksApp);
      } else {
        bootSparksApp();
      }
    